import itertools

def get_sets(matrix):
    m = len(matrix)
    X = [set(row) for row in matrix]
    Y = [set(matrix[i][j] for i in range(m)) for j in range(m)]
    return X, Y

def is_harmonious(matrix):
    X, Y = get_sets(matrix)
    all_sets = []
    for s in X:
        all_sets.append(frozenset(s))
    for s in Y:
        all_sets.append(frozenset(s))
    return len(set(all_sets)) == 2 * len(matrix)

def solve_small(m, n):
    import itertools
    # Each element in the matrix can be 1 to n.
    # m*m elements.
    # This is too large for brute force.
    # Let's try a randomized approach.
    import random
    for _ in range(100000):
        matrix = [[random.randint(1, n) for _ in range(m)] for _ in range(m)]
        if is_harmonious(matrix):
            return matrix
    return None

for m in range(2, 5):
    for n in range(1, 10):
        res = solve_small(m, n)
        if res:
            print(f"m={m}, n={n} is possible")
            break

