import itertools

def get_dual(X, n):
    dual = []
    for s in itertools.product([0, 1], repeat=n):
        S = set([i for i, val in enumerate(s) if val])
        if all(S.intersection(x) for x in X):
            dual.append(frozenset(S))
    return set(dual)

def max_union(n):
    # This is too slow for large n.
    # Let's try a random search for X.
    import random
    best = 0
    for _ in range(1000):
        X_size = random.randint(1, 2**n)
        X = [frozenset(random.sample(range(n), random.randint(0, n))) for _ in range(X_size)]
        X = set(X)
        dual = get_dual(X, n)
        best = max(best, len(X | dual))
    return best

for n in range(1, 6):
    print(f"n={n}, max_union={max_union(n)}")

import itertools

def get_dual(X, n):
    dual = []
    for s in itertools.product([0, 1], repeat=n):
        S = frozenset([i for i, val in enumerate(s) if val])
        if all(S.intersection(x) for x in X):
            dual.append(S)
    return set(dual)

def check_n(n, m):
    # Try a few random X sets of size m
    import random
    for _ in range(1000):
        # Randomly pick m subsets of {0, ..., n-1}
        X = set()
        while len(X) < m:
            X.add(frozenset(random.sample(range(n), random.randint(0, n))))

        dual = get_dual(X, n)
        if len(dual - X) >= m:
            return True
    return False

for n in range(1, 7):
    for m in range(1, 10):
        if check_n(n, m):
            print(f"n={n}, m={m} possible")
